import { useState, useEffect } from "react";
import { Card } from "@/components/ui/card";
import { TrendingUp, TrendingDown, Activity } from "lucide-react";
import { apiClient } from "@/lib/api-client";

interface TickerData {
  symbol: string;
  price: number;
  change: number;
  changePercent: number;
}

export const LivePriceTicker = () => {
  const [tickers, setTickers] = useState<TickerData[]>([]);
  const [loading, setLoading] = useState(true);

  const symbols = ['SPY', 'AAPL', 'TSLA', 'MSFT'];

  const fetchTickerData = async () => {
    try {
      const response = await apiClient.getRealtimeQuotes(symbols);

      if (response && response.quotes) {
        const tickerData: TickerData[] = symbols.map(symbol => {
          const quote = response.quotes[symbol];
          if (!quote) return null;

          const currentPrice = quote.ap || quote.bp || 0;
          const prevClose = quote.pc || currentPrice;
          const change = currentPrice - prevClose;
          const changePercent = prevClose > 0 ? (change / prevClose) * 100 : 0;

          return {
            symbol,
            price: currentPrice,
            change,
            changePercent
          };
        }).filter(Boolean) as TickerData[];

        setTickers(tickerData);
      }
      setLoading(false);
    } catch (error: any) {
      console.error('Error fetching ticker data:', error);
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTickerData();
    // Refresh every 10 seconds for realtime updates
    const interval = setInterval(fetchTickerData, 10000);
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <Card className="p-4 bg-gradient-to-r from-primary/10 to-secondary/10 border-primary/20">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Activity className="h-4 w-4 animate-pulse" />
          Loading market data...
        </div>
      </Card>
    );
  }

  // Show friendly message when no market data is available
  if (tickers.length === 0) {
    return (
      <Card className="p-4 bg-gradient-to-r from-blue-500/10 to-cyan-500/10 border-blue-500/20">
        <div className="flex items-center gap-3 text-sm">
          <Activity className="h-4 w-4 text-blue-500" />
          <div>
            <div className="font-semibold text-blue-600 dark:text-blue-400">Market data temporarily unavailable</div>
            <div className="text-xs text-muted-foreground mt-0.5">
              API rate limits active. Your portfolio and trading functions are unaffected. Data will resume automatically when limits reset.
            </div>
          </div>
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-4 bg-gradient-to-r from-primary/10 to-secondary/10 border-primary/20">
      <div className="flex items-center justify-between gap-6 overflow-x-auto">
        <div className="flex items-center gap-2 text-sm font-semibold text-primary whitespace-nowrap">
          <Activity className="h-4 w-4" />
          LIVE MARKET
        </div>
        
        <div className="flex items-center gap-6 flex-1 justify-end">
          {tickers.map((ticker) => (
            <div key={ticker.symbol} className="flex items-center gap-3 whitespace-nowrap">
              <div className="text-sm font-bold">{ticker.symbol}</div>
              <div className="text-lg font-bold">${ticker.price.toFixed(2)}</div>
              <div className={`flex items-center gap-1 text-sm font-semibold ${
                ticker.change >= 0 ? 'text-green-500' : 'text-red-500'
              }`}>
                {ticker.change >= 0 ? (
                  <TrendingUp className="h-4 w-4" />
                ) : (
                  <TrendingDown className="h-4 w-4" />
                )}
                <span>{ticker.change >= 0 ? '+' : ''}{ticker.changePercent.toFixed(2)}%</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Card>
  );
};
